package vn.edu.eaut.lab7.repository; import vn.edu.eaut.lab7.model.*; import java.util.*; import java.util.stream.*; public class SinhVienRepository { private static final List<SinhVien> data=new ArrayList<>(List.of(new SinhVien(1,"SV001","Nguyễn Văn An","an@gmail.com","0900000001"),new SinhVien(2,"SV002","Trần Thị Bình","binh@gmail.com","0900000002"))); private static int next=3; public List<SinhVien> findAll(){return data;} public SinhVien findById(int id){return data.stream().filter(x->x.getId()==id).findFirst().orElse(null);} public void add(SinhVien x){x.setId(next++);data.add(x);} public void update(SinhVien x){SinhVien o=findById(x.getId());if(o!=null){o.setMa(x.getMa());o.setHoTen(x.getHoTen());o.setEmail(x.getEmail());o.setSoDienThoai(x.getSoDienThoai());}} public void delete(int id){data.removeIf(x->x.getId()==id);} public List<SinhVien> search(String k){if(k==null||k.isBlank())return data;String q=k.toLowerCase();return data.stream().filter(x->x.getMa().toLowerCase().contains(q)||x.getHoTen().toLowerCase().contains(q)).collect(Collectors.toList());} }